  input: { backgroundColor: '#1e293b', padding: 10, borderRadius: 8, color: '#fff', fontSize: 13 },
  errorText: { color: '#ef4444', backgroundColor: 'rgba(239,68,68,0.1)', padding: 8, borderRadius: 6, marginBottom: 12, fontSize: 12 }
